use std::{fs,path::PathBuf,io::Seek};
use lin::persist::{append_record,for_each_wal_frame};
fn main(){let args:Vec<String>=std::env::args().collect();let input=PathBuf::from(&args[1]);let dest=PathBuf::from(&args[2]);assert!(!dest.exists());fs::create_dir(&dest).unwrap();for case in ["id_uri","uri_only","stale_id_uri_fallback","facts_tuple","facts_missing_part","custom_id","custom_no_identity","nested_batch"] {
 let source=fs::read(input.join(format!("{case}-full.wal"))).unwrap();let expected=fs::read(input.join(format!("{case}-keys.wal"))).unwrap();let target=dest.join(format!("{case}-keys.wal"));let mut file=fs::OpenOptions::new().write(true).create_new(true).open(&target).unwrap();let mut count=0;let mut buf=Vec::new();assert_eq!(for_each_wal_frame(&source,|record|{append_record(&mut file,&record,&mut buf,lin::SyncMode::Full,&mut count)?;Ok(())}).unwrap(),2);assert_eq!(file.stream_position().unwrap(),count);drop(file);let actual=fs::read(&target).unwrap();assert_eq!(actual,expected);fs::write(dest.join(format!("{case}-full.wal")),source).unwrap();fs::copy(input.join(format!("{case}.expected")),dest.join(format!("{case}.expected"))).unwrap();println!("{}",serde_json::json!({"case":case,"production_bytes_exactly_match_legacy_qualified_fixture":true,"total_stream_bytes":count,"performance_qualified":false}));}}
